INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''ginning'' and where does it fit relative to the spinning process (before or after)?', '["Ginning separates raw cotton fiber (lint) from cotton seeds; it happens BEFORE spinning, at the cotton processing/ginnery stage","Ginning is the final step of spinning, inserting the last twist into finished yarn","Ginning happens between carding and drawing, within the spinning mill itself","Ginning is a synonym for combing, performed at the comber machine"]'::jsonb, 'Ginning separates raw cotton fiber (lint) from cotton seeds; it happens BEFORE spinning, at the cotton processing/ginnery stage', 'Ginning is an agricultural/post-harvest processing step (at a cotton gin) that separates cotton lint (fiber) from seeds and baled for shipment to spinning mills — it precedes all spinning mill operations like blow room, carding, etc.', 1, '{"ginning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does a ''roller gin'' versus a ''saw gin'' generally differ in, regarding effect on fiber quality?', '["Roller gins tend to be gentler on fiber (less damage, often used for long-staple/extra-fine cotton), while saw gins are faster but can be more aggressive on fiber","Saw gins are always gentler on fiber than roller gins in every case","Both gin types produce chemically different cotton fiber, unrelated to any mechanical action","Roller gins are used exclusively for synthetic fiber, never natural cotton"]'::jsonb, 'Roller gins tend to be gentler on fiber (less damage, often used for long-staple/extra-fine cotton), while saw gins are faster but can be more aggressive on fiber', 'Roller gins use a gentler nipping/pulling action suited to delicate long-staple cottons (like Egyptian/Pima), while saw gins use rotating circular saws to pull fiber through narrow slots — faster and higher-capacity but potentially more damaging to fiber, typically used for shorter-staple upland cotton.', 2, '{"ginning-methods"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does excessive mechanical stress during ginning or opening potentially reduce spinnability of cotton fiber?', '["It can break/shorten fibers and create more neps, reducing the effective usable fiber length and increasing processing difficulty","Mechanical stress during ginning always improves fiber length with no downside","Ginning has zero relationship to fiber length or spinnability","Mechanical stress only affects fiber color, never its physical structure"]'::jsonb, 'It can break/shorten fibers and create more neps, reducing the effective usable fiber length and increasing processing difficulty', 'Overly aggressive mechanical handling (in ginning, opening, or other early processing) can physically break/damage fibers, shortening effective staple length and creating tangled neps — both of which reduce the fiber''s spinnability and the resulting yarn''s quality potential.', 2, '{"fiber-damage","spinnability"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is ''blending'' at the fiber stage (before or during opening/carding) primarily meant to achieve?', '["Combining different cotton lots (or different fiber types, like cotton/polyester) to achieve consistent, targeted properties in the final yarn","Physically dyeing raw fiber a uniform color before any spinning begins","Removing all twist from previously spun yarn","Measuring the exact final count of finished yarn"]'::jsonb, 'Combining different cotton lots (or different fiber types, like cotton/polyester) to achieve consistent, targeted properties in the final yarn', 'Blending mixes different fiber lots/types (different cotton bales, or cotton with synthetic fiber) in controlled proportions to average out quality variation and/or achieve specific target properties (strength, cost, performance) in the resulting yarn.', 1, '{"fiber-blending"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'In a cotton/polyester blend yarn (e.g., 65/35 polyester/cotton), what is a common motivation for including polyester alongside cotton?', '["Polyester generally adds strength and wrinkle/shrinkage resistance while cotton contributes comfort/breathability — the blend balances these complementary properties","Polyester is included purely to change the yarn''s final color, with no effect on strength or wrinkle resistance","Cotton is included solely to increase cost with no functional benefit","Blending these two fibers has no effect on any yarn property compared to either fiber alone"]'::jsonb, 'Polyester generally adds strength and wrinkle/shrinkage resistance while cotton contributes comfort/breathability — the blend balances these complementary properties', 'This is a classic complementary blend: cotton offers natural comfort, breathability, and moisture absorption, while polyester contributes strength, wrinkle resistance, and dimensional stability — combining them balances comfort with easier-care performance.', 1, '{"polyester-cotton-blend"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is ''intimate blending'' (fiber-level blending, e.g., at the blow room/carding stage) versus ''yarn-level'' blending (e.g., plying two different single yarns together)?', '["Intimate blending mixes different fiber types together at the individual fiber level before spinning into a single yarn, while yarn-level blending combines already-spun distinct yarns (e.g., plying a cotton single with a polyester single)","The two terms describe the exact same process with zero technical difference","Intimate blending can only be done after yarn is already finished, never before","Yarn-level blending mixes individual fibers together before any spinning occurs"]'::jsonb, 'Intimate blending mixes different fiber types together at the individual fiber level before spinning into a single yarn, while yarn-level blending combines already-spun distinct yarns (e.g., plying a cotton single with a polyester single)', 'Intimate blending combines different fiber types (e.g., cotton and polyester staple) together at the raw fiber stage so each single yarn contains an even mix of both fibers throughout; yarn-level blending instead spins each fiber type into its own single yarn first, then combines those distinct yarns together (e.g., via plying/twisting) — a structurally different approach to combining fiber properties.', 2, '{"intimate-blending","yarn-blending"}'::text[]);
